"""Summarize mailbox letters without changing the node."""
import argparse
from datetime import datetime, timedelta
import json
from pathlib import Path
import re


RESOLVED = {"DONE", "BLOCKED", "NEEDS-USER", "FAILED"}
NAME = re.compile(r"^([0-9]{8}T[0-9]{4})[-_]")


def read_letter(path, now):
    lines = path.read_text(encoding="utf-8", errors="replace").splitlines()
    if not lines or lines[0] != "---":
        return None, "no_frontmatter"
    try:
        end = lines.index("---", 1)
    except ValueError:
        return None, "no_frontmatter"
    fields = {}
    for line in lines[1:end]:
        key, separator, value = line.partition(": ")
        if separator:
            fields[key] = value
    if any(not fields.get(key) for key in ("id", "from", "to", "status")):
        return None, "no_field"
    try:
        at = datetime.fromisoformat(fields.get("at", ""))
    except ValueError:
        return None, "no_field"
    if at.tzinfo is None:
        at = at.replace(tzinfo=now.tzinfo)
    match = NAME.match(path.name)
    if not match:
        return None, "bad_name"
    try:
        datetime.strptime(match.group(1), "%Y%m%dT%H%M")
    except ValueError:
        return None, "bad_name"
    return (fields, at), None


def summarize(root, now):
    boxes = {}
    candidates = []
    for mailbox in sorted(root.iterdir(), key=lambda path: path.name):
        if mailbox.name.startswith(".") or mailbox.is_symlink() or not mailbox.is_dir():
            continue
        inbox = mailbox / "inbox"
        if inbox.is_symlink() or not inbox.is_dir():
            continue
        boxes[mailbox.name] = {"inbox": {}, "done": 0}
        for where, directory in (("inbox", inbox), ("done", inbox / "done")):
            if directory.is_symlink() or not directory.is_dir():
                continue
            for path in directory.iterdir():
                if (not path.name.startswith(".") and path.suffix == ".md"
                        and not path.is_symlink() and path.is_file()):
                    candidates.append((path.relative_to(root).as_posix(), path, mailbox.name, where))

    bad = []
    valid = []
    seen = set()
    for relative, path, mailbox, where in sorted(candidates):
        letter, why = read_letter(path, now)
        if why is None and letter[0]["id"] in seen:
            why = "dup_id"
        if why is not None:
            bad.append({"file": relative, "why": why})
            continue
        fields, at = letter
        seen.add(fields["id"])
        valid.append((fields, at, mailbox, where))
        if where == "done":
            boxes[mailbox]["done"] += 1
        else:
            counts = boxes[mailbox]["inbox"]
            counts[fields["status"]] = counts.get(fields["status"], 0) + 1

    resolved = {fields.get("re") for fields, _, _, _ in valid
                if fields["status"] in RESOLVED and fields.get("re")}
    opened = []
    for fields, at, _, where in valid:
        if fields["status"] == "REQUEST" and fields["id"] not in resolved:
            opened.append({"id": fields["id"], "from": fields["from"],
                           "to": fields["to"], "where": where,
                           "age_min": (now - at) // timedelta(minutes=1)})
    opened.sort(key=lambda item: (item["to"], item["id"]))
    return {"v": 1, "open": opened, "boxes": boxes, "bad": bad}


def main(argv=None):
    parser = argparse.ArgumentParser(description="Read-only mailbox todo summary")
    parser.add_argument("folder", type=Path)
    parser.add_argument("--now", required=True)
    args = parser.parse_args(argv)
    try:
        now = datetime.fromisoformat(args.now)
    except ValueError:
        parser.error("--now must be an ISO datetime with a timezone")
    if now.tzinfo is None:
        parser.error("--now must have a timezone")
    if not args.folder.is_dir():
        parser.error("folder must be a directory")
    print(json.dumps(summarize(args.folder, now), ensure_ascii=False,
                     separators=(",", ":"), sort_keys=True))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
